from datetime import date, timedelta

def dias_uteis_entre(data_inicial, data_final):
    if data_final < data_inicial:
        data_inicial, data_final = data_final, data_inicial

    contador = 0
    dia = data_inicial
    while dia <= data_final:
        if dia.weekday() < 5:
            contador += 1
        dia += timedelta(days=1)
    return contador

